1	// Package relayproof implements cross-chain message verification.
2	package relayproof
3	
4	import (
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sort"
10		"strconv"
11		"sync"
12		"syscall"
13	)
14	
15	// Durable queue statuses. Pending and waiting are live; the rest are terminal.
16	const (
17		StatusPending    = "pending"        // accepted, not processed for the first time yet
18		StatusWaiting    = "waiting"        // processed, waiting for a trusted header at proof height
19		StatusSuccess    = "success"        // recorded locally and nonce consumed
20		StatusReplay     = "replay"         // nonce combination already consumed by another message
21		StatusExpired    = "expired"        // absolute expiry reached before delivery
22		StatusUnknownSrc = "unknown-source" // source chain was never registered
23	)
24	
25	// Common errors. Callers can compare with errors.Is.
26	var (
27		// ErrConflict is returned when an id is reused with different message content.
28		ErrConflict = errors.New("message id conflict: existing record has different content")
29		// ErrHeaderConflict is returned when a trusted header is submitted at the
30		// height of the accepted highest trusted header with a different root. The
31		// accepted trusted header is kept and the queue remains usable.
32		ErrHeaderConflict = errors.New("trusted header conflict: different root at the accepted height")
33		// ErrTerminal is returned when re-submitting a terminal id or attempting to
34		// reactivate it.
35		ErrTerminal = errors.New("message is terminal and cannot be reactivated")
36		// ErrInvalidArg is returned for malformed input (empty id, bad times, ...).
37		ErrInvalidArg = errors.New("invalid argument")
38		// ErrLocked is returned when another process holds the state directory open.
39		ErrLocked = errors.New("state directory is locked by another process")
40		// ErrCorrupt is returned when on-disk state is unreadable or unsupported.
41		ErrCorrupt = errors.New("state directory is corrupt or uses an unsupported format")
42		// ErrStorage is returned after a storage failure; the queue must be reopened.
43		ErrStorage = errors.New("storage failure; queue must be reopened")
44	)
45	
46	// Envelope is a submitted message together with its absolute expiry time.
47	type Envelope struct {
48		Message Message
49		// ExpiresAt is an absolute Unix-millisecond instant. Zero means never expire.
50		ExpiresAt int64
51	}
52	
53	// Record is the full persisted state of one submitted message.
54	type Record struct {
55		Msg        Envelope
56		Status     string
57		Reason     string
58		Seq        int64 // submission order, zero-based
59		Attempts   int   // number of processing attempts
60		NextRetry  int64 // 0 when not yet processed, or terminal
61		LastProcAt int64 // processing time of the most recent attempt
62	}
63	
64	// Query is the user-visible view of a Record.
65	type Query struct {
66		ID        string
67		From      string
68		To        string
69		Nonce     uint64
70		Payload   string
71		ProofAt   int64
72		ExpiresAt int64
73		Status    string
74		Reason    string
75		NextRetry int64 // 0 = no retry scheduled (not yet processed, or terminal)
76		Attempts  int
77	}
78	
79	// AdvanceReport is the outcome of one Advance call.
80	type AdvanceReport struct {
81		Now     int64
82		Results []Result
83	}
84	
85	// Result describes what happened to one message during an Advance.
86	type Result struct {
87		ID     string `json:"id"`
88		Status string `json:"status"`
89		Reason string `json:"reason"`
90	}
91	
92	// headerState records the headers seen for one chain: the latest header
93	// written (any trust level) and the highest trusted header accepted. Proof
94	// coverage is determined solely by the highest trusted header — a later
95	// untrusted header, even at a greater height, can never lower or invalidate
96	// it. The zero value is a chain with no recorded headers.
97	type headerState struct {
98		latest  Header
99		trusted *Header
100	}
101	
102	// Queue is a durable local outbox backed by a state directory. A single
103	// Queue owns the directory for writes; other processes attempting to Open the
104	// same directory fail with ErrLocked. It is safe for concurrent use by
105	// multiple goroutines, and a success record plus its nonce consumption commit
106	// as one durable unit.
107	type Queue struct {
108		mu sync.Mutex
109	
110		store  *store
111		flock  *os.File
112		broken bool // a storage write failed; all further mutations fail
113	
114		now      int64                   // last advanced Unix-ms time, 0 = never advanced
115		sources  map[string]bool         // registered source chains
116		headers  map[string]*headerState // per-chain recorded headers (latest + highest trusted)
117		records  map[string]*Record      // by message id
118		order    []string                // non-terminal messages, submission order
119		consumed map[consumeToken]string // (source, destination, nonce) -> successful message id
120		nextSeq  int64
121	}
122	
123	// Open opens (creating if needed) a persistent queue backed by stateDir. It
124	// takes an exclusive process lock on the directory and refuses to start when
125	// the on-disk state is corrupt or in an unsupported format, never clearing it.
126	func Open(stateDir string) (*Queue, error) {
127		if stateDir == "" {
128			return nil, fmt.Errorf("%w: empty state directory", ErrInvalidArg)
129		}
130		if err := os.MkdirAll(stateDir, 0o755); err != nil {
131			return nil, fmt.Errorf("create state directory: %w", err)
132		}
133		abs, err := filepath.Abs(stateDir)
134		if err != nil {
135			return nil, fmt.Errorf("resolve state directory: %w", err)
136		}
137	
138		lockPath := filepath.Join(abs, "lock")
139		lock, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
140		if err != nil {
141			return nil, fmt.Errorf("open lock file: %w", err)
142		}
143		if err := syscall.Flock(int(lock.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
144			lock.Close()
145			return nil, fmt.Errorf("%w: %v", ErrLocked, err)
146		}
147	
148		st, state, err := openStore(abs)
149		if err != nil {
150			syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)
151			lock.Close()
152			return nil, err
153		}
154	
155		q := &Queue{
156			store:    st,
157			flock:    lock,
158			sources:  state.sources,
159			headers:  state.headers,
160			records:  state.records,
161			consumed: state.consumed,
162			now:      state.now,
163			nextSeq:  state.nextSeq,
164		}
165		q.order = q.reconstructOrder()
166		st.snap = q.snapshot
167		return q, nil
168	}
169	
170	// reconstructOrder returns non-terminal record ids in submission (seq) order.
171	func (q *Queue) reconstructOrder() []string {
172		seqs := make([]int64, 0, len(q.records))
173		live := map[int64]string{}
174		for id, rec := range q.records {
175			if isTerminal(rec.Status) {
176				continue
177			}
178			seqs = append(seqs, rec.Seq)
179			live[rec.Seq] = id
180		}
181		sort.Slice(seqs, func(i, j int) bool { return seqs[i] < seqs[j] })
182		order := make([]string, 0, len(seqs))
183		for _, seq := range seqs {
184			order = append(order, live[seq])
185		}
186		return order
187	}
188	
189	// snapshot returns a detached copy of live state for log compaction. Callers
190	// must hold mu.
191	func (q *Queue) snapshot() *loadedState {
192		s := &loadedState{
193			sources:  map[string]bool{},
194			headers:  map[string]*headerState{},
195			records:  map[string]*Record{},
196			consumed: map[consumeToken]string{},
197			now:      q.now,
198			nextSeq:  q.nextSeq,
199		}
200		for c := range q.sources {
201			s.sources[c] = true
202		}
203		for c, h := range q.headers {
204			cp := &headerState{latest: h.latest}
205			if h.trusted != nil {
206				t := *h.trusted
207				cp.trusted = &t
208			}
209			s.headers[c] = cp
210		}
211		for id, rec := range q.records {
212			cp := *rec
213			s.records[id] = &cp
214		}
215		for k, v := range q.consumed {
216			s.consumed[k] = v
217		}
218		return s
219	}
220	
221	// Close flushes, releases the directory lock and closes the queue.
222	func (q *Queue) Close() error {
223		q.mu.Lock()
224		defer q.mu.Unlock()
225		if q.flock == nil {
226			return nil
227		}
228		var err error
229		if !q.broken {
230			err = q.store.close()
231		} else {
232			q.store.forceClose()
233		}
234		syscall.Flock(int(q.flock.Fd()), syscall.LOCK_UN)
235		q.flock.Close()
236		q.flock = nil
237		return err
238	}
239	
240	// fail locks in a storage failure: the log tail may be partially written, so
241	// no further appends are allowed in this process (another append would turn a
242	// truncatable torn tail into unrecoverable corruption).
243	func (q *Queue) fail(op string, err error) error {
244		q.broken = true
245		return fmt.Errorf("%w: %s: %v", ErrStorage, op, err)
246	}
247	
248	func (q *Queue) checkWritable() error {
249		if q.flock == nil {
250			return fmt.Errorf("%w: queue is closed", ErrStorage)
251		}
252		if q.broken {
253			return fmt.Errorf("%w: a previous write failed; reopen the queue", ErrStorage)
254		}
255		return nil
256	}
257	
258	// RegisterSource records that messages may originate from chain. Idempotent.
259	func (q *Queue) RegisterSource(chain string) error {
260		if chain == "" {
261			return fmt.Errorf("%w: empty source chain", ErrInvalidArg)
262		}
263		q.mu.Lock()
264		defer q.mu.Unlock()
265		if err := q.checkWritable(); err != nil {
266			return err
267		}
268		if q.sources[chain] {
269			return nil
270		}
271		if err := q.store.appendRegisterSource(chain); err != nil {
272			return q.fail("register source", err)
273		}
274		q.sources[chain] = true
275		return q.maybeCompact()
276	}
277	
278	// UpsertHeader records a header for a chain. The latest header is always
279	// recorded, but proof coverage is determined solely by the highest trusted
280	// header accepted for the chain:
281	//
282	//   - the first trusted header establishes coverage;
283	//   - a higher trusted header advances it;
284	//   - a lower trusted header, or an untrusted header of any height, is
285	//     recorded but can never lower or invalidate established coverage;
286	//   - a trusted header at the current highest trusted height with the same
287	//     root is an idempotent no-op;
288	//   - a trusted header at that height with a different root is an
289	//     ErrHeaderConflict: the accepted trusted header is kept and the queue
290	//     remains usable.
291	//
292	// Header updates never bypass retry scheduling, never process messages, and
293	// never reactivate terminal messages.
294	func (q *Queue) UpsertHeader(h Header) error {
295		if h.Chain == "" {
296			return fmt.Errorf("%w: empty header chain", ErrInvalidArg)
297		}
298		if h.Height < 0 {
299			return fmt.Errorf("%w: negative header height", ErrInvalidArg)
300		}
301		q.mu.Lock()
302		defer q.mu.Unlock()
303		if err := q.checkWritable(); err != nil {
304			return err
305		}
306		hs := q.headers[h.Chain]
307		if hs == nil {
308			hs = &headerState{}
309			q.headers[h.Chain] = hs
310		}
311		if h.Trusted && hs.trusted != nil &&
312			h.Height == hs.trusted.Height && h.Root != hs.trusted.Root {
313			return fmt.Errorf("%w: chain %q height %d: submitted root %q conflicts with accepted root %q",
314				ErrHeaderConflict, h.Chain, h.Height, h.Root, hs.trusted.Root)
315		}
316		if err := q.store.appendHeader(h); err != nil {
317			return q.fail("upsert header", err)
318		}
319		hs.latest = h
320		if h.Trusted && (hs.trusted == nil || h.Height > hs.trusted.Height) {
321			t := h
322			hs.trusted = &t
323		}
324		return q.maybeCompact()
325	}
326	
327	// Submit enqueues a message with an absolute expiry (Unix milliseconds; zero
328	// means never expire). Re-submitting the same id with identical content
329	// returns the existing record without adding a queue entry; the same id with
330	// different content returns ErrConflict and leaves the original untouched;
331	// re-submitting a terminal id returns ErrTerminal. Success is reported only
332	// after the submission is durably persisted.
333	func (q *Queue) Submit(env Envelope) (*Record, error) {
334		m := env.Message
335		if m.ID == "" {
336			return nil, fmt.Errorf("%w: empty message id", ErrInvalidArg)
337		}
338		if m.From == "" || m.To == "" {
339			return nil, fmt.Errorf("%w: empty source or destination chain", ErrInvalidArg)
340		}
341		if m.ProofAt < 0 {
342			return nil, fmt.Errorf("%w: negative proof height", ErrInvalidArg)
343		}
344		if env.ExpiresAt < 0 {
345			return nil, fmt.Errorf("%w: negative expiry time", ErrInvalidArg)
346		}
347	
348		q.mu.Lock()
349		defer q.mu.Unlock()
350		if err := q.checkWritable(); err != nil {
351			return nil, err
352		}
353	
354		if existing, ok := q.records[m.ID]; ok {
355			if isTerminal(existing.Status) {
356				return nil, fmt.Errorf("%w: message %s is %s", ErrTerminal, m.ID, existing.Status)
357			}
358			if sameEnvelope(existing.Msg, env) {
359				out := *existing
360				return &out, nil
361			}
362			return nil, fmt.Errorf("%w: message %s", ErrConflict, m.ID)
363		}
364	
365		rec := &Record{
366			Msg:    env,
367			Status: StatusPending,
368			Reason: "awaiting first processing",
369			Seq:    q.nextSeq,
370		}
371		if err := q.store.appendSubmit(rec); err != nil {
372			return nil, q.fail("submit", err)
373		}
374		q.records[m.ID] = rec
375		q.order = append(q.order, m.ID)
376		q.nextSeq++
377		if err := q.maybeCompact(); err != nil {
378			return nil, err
379		}
380		out := *rec
381		return &out, nil
382	}
383	
384	// Advance moves processing time to nowMs (Unix milliseconds). Equal time may
385	// be advanced repeatedly; going backwards is rejected and changes nothing.
386	//
387	// Each advance, in submission order:
388	//  1. due messages (new messages are due on the next advance; others when now
389	//     has reached their next retry time) are evaluated for replay and expiry,
390	//     replay winning on a tie and now == ExpiresAt counting as expired, then
391	//     for source registration and trusted-header coverage, and finally
392	//     delivered;
393	//  2. afterwards every remaining non-terminal message, regardless of its
394	//     retry schedule, is re-checked for replay and expiry at the new time.
395	//
396	// Unregistered sources are permanently rejected as unknown-source; registered
397	// sources without a trusted header covering the proof height stay waiting and
398	// do not consume the nonce. Waiting retry intervals are 1,2,4,... seconds,
399	// doubling to a 60-second cap, measured from the actual processing time;
400	// jumping over several intervals still costs one attempt.
401	func (q *Queue) Advance(nowMs int64) (*AdvanceReport, error) {
402		if nowMs < 0 {
403			return nil, fmt.Errorf("%w: negative processing time", ErrInvalidArg)
404		}
405		q.mu.Lock()
406		defer q.mu.Unlock()
407		if err := q.checkWritable(); err != nil {
408			return nil, err
409		}
410		if q.now != 0 && nowMs < q.now {
411			return nil, fmt.Errorf("%w: processing time %d precedes last advanced time %d", ErrInvalidArg, nowMs, q.now)
412		}
413	
414		report := &AdvanceReport{Now: nowMs}
415	
416		// Phase 1: due messages, first-submission order.
417		for _, id := range append([]string(nil), q.order...) {
418			rec := q.records[id]
419			if rec == nil || isTerminal(rec.Status) {
420				continue
421			}
422			due := rec.Attempts == 0 || nowMs >= rec.NextRetry
423			if !due {
424				continue
425			}
426			if r, done, err := q.checkReplayExpiry(rec, nowMs); err != nil {
427				return nil, err
428			} else if done {
429				report.Results = append(report.Results, r)
430				continue
431			}
432			r, err := q.processDue(rec, nowMs)
433			if err != nil {
434				return nil, err
435			}
436			report.Results = append(report.Results, r)
437		}
438	
439		// Phase 2: replay/expiry hold for every non-terminal message at the new
440		// time, even while its retry backoff is still running.
441		for _, id := range append([]string(nil), q.order...) {
442			rec := q.records[id]
443			if rec == nil || isTerminal(rec.Status) {
444				continue
445			}
446			if r, done, err := q.checkReplayExpiry(rec, nowMs); err != nil {
447				return nil, err
448			} else if done {
449				report.Results = append(report.Results, r)
450			}
451		}
452	
453		if err := q.store.appendAdvance(nowMs); err != nil {
454			return nil, q.fail("advance", err)
455		}
456		q.now = nowMs
457		if err := q.maybeCompact(); err != nil {
458			return nil, err
459		}
460		return report, nil
461	}
462	
463	// maybeCompact rewrites the WAL as a snapshot once it grows past the
464	// threshold. Live state already reflects every acknowledged append, so the
465	// snapshot cannot lose records. A compaction failure is a storage failure:
466	// the queue is marked broken and must be reopened.
467	func (q *Queue) maybeCompact() error {
468		if !q.store.needsCompaction() {
469			return nil
470		}
471		if err := q.store.compact(q.snapshot()); err != nil {
472			return q.fail("compact log", err)
473		}
474		return nil
475	}
476	
477	// checkReplayExpiry terminalizes rec when its nonce was consumed by another
478	// message or its absolute expiry has been reached. Replay wins when both
479	// hold. The bool reports whether the message was terminalized.
480	func (q *Queue) checkReplayExpiry(rec *Record, now int64) (Result, bool, error) {
481		id := rec.Msg.Message.ID
482		token := newConsumeToken(rec.Msg.Message.From, rec.Msg.Message.To, rec.Msg.Message.Nonce)
483		if winner, taken := q.consumed[token]; taken && winner != id {
484			reason := "nonce combination already consumed by message " + winner
485			if err := q.terminalize(rec, now, StatusReplay, reason); err != nil {
486				return Result{}, false, err
487			}
488			return Result{ID: id, Status: StatusReplay, Reason: reason}, true, nil
489		}
490		if rec.Msg.ExpiresAt != 0 && now >= rec.Msg.ExpiresAt {
491			reason := "expired at " + strconv.FormatInt(rec.Msg.ExpiresAt, 10)
492			if err := q.terminalize(rec, now, StatusExpired, reason); err != nil {
493				return Result{}, false, err
494			}
495			return Result{ID: id, Status: StatusExpired, Reason: reason}, true, nil
496		}
497		return Result{}, false, nil
498	}
499	
500	// processDue classifies a due message against source registration and header
501	// trust, or delivers it.
502	func (q *Queue) processDue(rec *Record, now int64) (Result, error) {
503		id := rec.Msg.Message.ID
504		if !q.sources[rec.Msg.Message.From] {
505			reason := "unknown source chain " + rec.Msg.Message.From
506			if err := q.terminalize(rec, now, StatusUnknownSrc, reason); err != nil {
507				return Result{}, err
508			}
509			return Result{ID: id, Status: StatusUnknownSrc, Reason: reason}, nil
510		}
511		hs := q.headers[rec.Msg.Message.From]
512		if hs == nil || hs.trusted == nil || hs.trusted.Height < rec.Msg.Message.ProofAt {
513			cur := int64(0)
514			if hs != nil && hs.trusted != nil {
515				cur = hs.trusted.Height
516			}
517			reason := fmt.Sprintf("waiting for trusted header covering height %d (current %d)", rec.Msg.Message.ProofAt, cur)
518			if err := q.markWaiting(rec, now, reason); err != nil {
519				return Result{}, err
520			}
521			return Result{ID: id, Status: StatusWaiting, Reason: reason}, nil
522		}
523	
524		// Deliver: success record and nonce consumption are one log entry. The
525		// coverage height is the highest trusted header actually accepted — never
526		// a higher untrusted header.
527		token := newConsumeToken(rec.Msg.Message.From, rec.Msg.Message.To, rec.Msg.Message.Nonce)
528		reason := "delivered; proof verified by trusted header at height " + strconv.FormatInt(hs.trusted.Height, 10)
529		if err := q.store.appendResult(now, rec, StatusSuccess, reason, rec.Attempts+1, &token, id); err != nil {
530			return Result{}, q.fail("deliver", err)
531		}
532		rec.Attempts++
533		rec.LastProcAt = now
534		rec.Status = StatusSuccess
535		rec.Reason = reason
536		rec.NextRetry = 0
537		q.consumed[token] = id
538		q.removeFromOrder(id)
539		return Result{ID: id, Status: StatusSuccess, Reason: reason}, nil
540	}
541	
542	func (q *Queue) terminalize(rec *Record, now int64, status, reason string) error {
543		if err := q.store.appendResult(now, rec, status, reason, rec.Attempts+1, nil, ""); err != nil {
544			return q.fail("terminalize", err)
545		}
546		rec.Attempts++
547		rec.LastProcAt = now
548		rec.Status = status
549		rec.Reason = reason
550		rec.NextRetry = 0
551		q.removeFromOrder(rec.Msg.Message.ID)
552		return nil
553	}
554	
555	func (q *Queue) markWaiting(rec *Record, now int64, reason string) error {
556		attempt := rec.Attempts + 1
557		if err := q.store.appendResult(now, rec, StatusWaiting, reason, attempt, nil, ""); err != nil {
558			return q.fail("schedule retry", err)
559		}
560		rec.Attempts = attempt
561		rec.LastProcAt = now
562		rec.Status = StatusWaiting
563		rec.Reason = reason
564		rec.NextRetry = now + nextRetryDelay(attempt)
565		return nil
566	}
567	
568	func (q *Queue) removeFromOrder(id string) {
569		for i, cand := range q.order {
570			if cand == id {
571				q.order = append(q.order[:i], q.order[i+1:]...)
572				return
573			}
574		}
575	}
576	
577	// nextRetryDelay is the backoff after the attempt-th processing (1-based):
578	// 1s, 2s, 4s, 8s, 16s, 32s, then 60s capped, in milliseconds.
579	func nextRetryDelay(attempt int) int64 {
580		if attempt < 1 {
581			attempt = 1
582		}
583		if attempt > 6 {
584			return 60_000
585		}
586		return int64(1) << (attempt - 1) * 1000
587	}
588	
589	func isTerminal(status string) bool {
590		switch status {
591		case StatusSuccess, StatusReplay, StatusExpired, StatusUnknownSrc:
592			return true
593		}
594		return false
595	}
596	
597	func sameEnvelope(a, b Envelope) bool {
598		return a.ExpiresAt == b.ExpiresAt &&
599			a.Message.ID == b.Message.ID &&
600			a.Message.From == b.Message.From &&
601			a.Message.To == b.Message.To &&
602			a.Message.Nonce == b.Message.Nonce &&
603			a.Message.Payload == b.Message.Payload &&
604			a.Message.ProofAt == b.Message.ProofAt
605	}
606	
607	// Query returns the current state of a message.
608	func (q *Queue) Query(id string) (Query, bool) {
609		q.mu.Lock()
610		defer q.mu.Unlock()
611		rec, ok := q.records[id]
612		if !ok {
613			return Query{}, false
614		}
615		return toQuery(rec), true
616	}
617	
618	// Queries returns all records in first-submission order.
619	func (q *Queue) Queries() []Query {
620		q.mu.Lock()
621		defer q.mu.Unlock()
622		out := make([]Query, 0, len(q.records))
623		for _, rec := range q.records {
624			out = append(out, toQuery(rec))
625		}
626		sort.Slice(out, func(i, j int) bool {
627			return q.records[out[i].ID].Seq < q.records[out[j].ID].Seq
628		})
629		return out
630	}
631	
632	// Now returns the last advanced processing time, or 0 if never advanced.
633	func (q *Queue) Now() int64 {
634		q.mu.Lock()
635		defer q.mu.Unlock()
636		return q.now
637	}
638	
639	func toQuery(rec *Record) Query {
640		return Query{
641			ID:        rec.Msg.Message.ID,
642			From:      rec.Msg.Message.From,
643			To:        rec.Msg.Message.To,
644			Nonce:     rec.Msg.Message.Nonce,
645			Payload:   rec.Msg.Message.Payload,
646			ProofAt:   rec.Msg.Message.ProofAt,
647			ExpiresAt: rec.Msg.ExpiresAt,
648			Status:    rec.Status,
649			Reason:    rec.Reason,
650			NextRetry: rec.NextRetry,
651			Attempts:  rec.Attempts,
652		}
653	}
