1	package relayproof
2	
3	import (
4		"bytes"
5		"encoding/binary"
6		"encoding/json"
7		"fmt"
8		"hash/crc32"
9		"io"
10		"os"
11		"path/filepath"
12		"sort"
13		"strconv"
14	)
15	
16	// On-disk format (queue.log):
17	//
18	//	magic   = "RELAYPROOF-QUEUE-V1\n"
19	//	frame   = uint32-be payload length(N) | N bytes JSON payload | uint32-be CRC32-IEEE(payload)
20	//
21	// The log is an append-only write-ahead log. Every mutating operation is
22	// persisted as one framed, checksummed record and fsynced before it is
23	// acknowledged; a success record frames the local success entry and the nonce
24	// consumption together, so the two can never take effect separately.
25	//
26	// A success (result or compacted state) names the consumed triple in three
27	// independent fields, consumeFrom/consumeTo/consumeNonce, alongside consumeBy.
28	// Chain names are stored verbatim as raw UTF-8 — they may contain ':' or even
29	// U+0000 — so the triple is never flattened into one delimiter-joined string,
30	// which would let distinct routing paths share one consumption identity.
31	//
32	// Crash recovery: a frame missing bytes at end of file, or a final frame with
33	// a bad checksum, is the torn tail of a write that was never acknowledged and
34	// is truncated. That recovery is only available once the log's leading
35	// version record has itself been read whole and verified: the magic alone
36	// never establishes a usable version, so a log whose very first record is
37	// partial (only some length bytes, or the length without the body and CRC),
38	// complete but checksum-bad, not a version record, or names an unsupported
39	// version is rejected wholesale with ErrCorrupt and left byte-for-byte
40	// untouched — it can never be truncated down to an empty-looking log that a
41	// later append would turn into a headerless one. Bad checksums or framing
42	// anywhere before the end, a foreign header, or an unsupported version
43	// likewise reject the directory with ErrCorrupt; state is never silently
44	// cleared.
45	//
46	// Logs written by older builds recorded the consumption as one NUL-joined
47	// consumeKey string. Such success entries are still accepted on replay: the
48	// key is validated against the record's own (from,to,nonce) and consumeBy,
49	// and only the record's own triple is marked consumed. A legacy key that does
50	// not match the record it is attached to — a genuinely inconsistent old
51	// record — rejects the whole directory with ErrCorrupt instead of silently
52	// accepting or "repairing" the bad entry.
53	
54	const (
55		logName          = "queue.log"
56		logMagic         = "RELAYPROOF-QUEUE-V1\n"
57		compactThreshold = 4 << 20 // compact when the active log grows past 4 MiB
58		compactFileMode  = 0o600
59		frameHeaderSize  = 4
60		frameCRCsSize    = 4
61	)
62	
63	var crcTable = crc32.MakeTable(crc32.IEEE)
64	
65	// JSON log entry kinds.
66	const (
67		kindVersion = "version"
68		kindSource  = "source"
69		kindHeader  = "header"
70		kindSubmit  = "submit"
71		kindResult  = "result"
72		kindState   = "state" // compacted snapshot: full status after >=1 attempts
73		kindAdvance = "advance"
74		currentLogV = 1
75	)
76	
77	type logEntry struct {
78		T string `json:"t"`
79		V int    `json:"v,omitempty"`
80	
81		Chain   string `json:"chain,omitempty"`
82		Height  int64  `json:"height,omitempty"`
83		Root    string `json:"root,omitempty"`
84		Trusted bool   `json:"trusted,omitempty"`
85	
86		Seq       int64  `json:"seq,omitempty"`
87		ID        string `json:"id,omitempty"`
88		From      string `json:"from,omitempty"`
89		To        string `json:"to,omitempty"`
90		Nonce     uint64 `json:"nonce,omitempty"`
91		Payload   string `json:"payload,omitempty"`
92		ProofAt   int64  `json:"proofAt,omitempty"`
93		ExpiresAt int64  `json:"expiresAt,omitempty"`
94	
95		Now       int64  `json:"now,omitempty"`
96		Status    string `json:"status,omitempty"`
97		Reason    string `json:"reason,omitempty"`
98		Attempts  int    `json:"attempts,omitempty"`
99		NextRetry int64  `json:"nextRetry,omitempty"`
100	
101		// Consumed triple of a success entry, stored as three independent values
102		// so routing paths that share a flattened key stay distinct. consumeBy is
103		// the id of the successful message.
104		ConsumeFrom  string `json:"consumeFrom,omitempty"`
105		ConsumeTo    string `json:"consumeTo,omitempty"`
106		ConsumeNonce uint64 `json:"consumeNonce,omitempty"`
107		ConsumeBy    string `json:"consumeBy,omitempty"`
108	
109		// ConsumeKey is the legacy (pre-triple) NUL-joined consumption string. It
110		// is accepted only while replaying logs written by older builds and is
111		// never written anymore.
112		ConsumeKey string `json:"consumeKey,omitempty"`
113	}
114	
115	// legacyNonceKey reproduces the consumption string used by older builds:
116	// from NUL to NUL nonce. It exists solely to validate records in pre-existing
117	// state directories; new state always uses consumeToken triples.
118	func legacyNonceKey(from, to string, nonce uint64) string {
119		return from + "\x00" + to + "\x00" + strconv.FormatUint(nonce, 10)
120	}
