139		}
140		if !strings.Contains(r.Reason, "ghost") {
141			t.Fatalf("reason should name the chain, got %q", r.Reason)
142		}
143		// Registering the source later must not resurrect a terminal record.
144		if err := q.RegisterSource("ghost"); err != nil {
145			t.Fatal(err)
146		}
