163		if _, err := q.Submit(e); err != nil {
164			t.Fatal(err)
165		}
166		before := len(q.order)
167		if _, err := q.Submit(e); err != nil {
168			t.Fatalf("identical resubmit must be idempotent: %v", err)
169		}
170		if len(q.order) != before || len(q.records) != 1 {
171			t.Fatalf("identical resubmit added a queue entry")
172		}
173	
174		diff := e
175		diff.Message.Payload = "changed"
176		if _, err := q.Submit(diff); !errors.Is(err, ErrConflict) {
177			t.Fatalf("want ErrConflict, got %v", err)
178		}
179		if got := statusOf(t, q, "m1"); got.Msg.Message.Payload != "p-m1" {
180			t.Fatalf("original record mutated by conflicting submit")
181		}
182	
183		// Same id, same content after terminalization is still rejected.
184		q.Advance(1000) // unknown? no, source a registered and no header -> waiting
185		q.UpsertHeader(Header{Chain: "a", Height: 100, Trusted: true})
186		q.Advance(2000) // success
187		if _, err := q.Submit(e); !errors.Is(err, ErrTerminal) {
188			t.Fatalf("resubmit of terminal id must be ErrTerminal, got %v", err)
189		}
190		if _, err := q.Submit(diff); !errors.Is(err, ErrTerminal) {
191			t.Fatalf("different content on terminal id must be ErrTerminal, got %v", err)
192		}
193	}
