603			t.Fatalf("partial m2 frame must be dropped")
604		}
605		qt.Close()
606	
607		// Flip a byte inside the middle frame (m1 body): checksum mismatch that is
608		// not at EOF must be fatal.
609		bad := append([]byte(nil), raw...)
610		pos := len(logMagic)
611		// Flip a byte inside the JSON body of the first frame (the version frame).
612		bad[pos+4+2] ^= 0xFF
613		badDir := t.TempDir()
614		os.WriteFile(filepath.Join(badDir, logName), bad, 0o600)
615		if _, err := Open(badDir); !errors.Is(err, ErrCorrupt) {
