11	// runVerify drives a deterministic scenario in a temporary (or --state given)
12	// directory so every terminal state, waiting, expiry, replay, restart and
13	// locking behaviour can be observed offline.
14	func runVerify(args []string) error {
15		stateDir := ""
16		for i := 0; i < len(args); i++ {
17			switch args[i] {
18			case "--state":
19				if i+1 >= len(args) {
20					return fmt.Errorf("--state requires a directory")
21				}
22				stateDir = args[i+1]
23				i++
24			default:
25				return fmt.Errorf("unknown verify flag %q", args[i])
26			}
27		}
28		if stateDir == "" {
29			var err error
30			stateDir, err = os.MkdirTemp("", "relayproof-verify-")
31			if err != nil {
32				return err
33			}
34			defer os.RemoveAll(stateDir)
35		}
36		fmt.Println("verify state dir:", stateDir)
37	
38		verifyAmbiguousPaths()
39	
40		must := func(step string, err error) {
41			if err != nil {
42				panic(step + ": " + err.Error())
43			}
44		}
45	
46		q, err := relayproof.Open(stateDir)
47		must("open", err)
48	
49		must("register a", q.RegisterSource("chain-a"))
50		must("header a@80 untrusted", q.UpsertHeader(relayproof.Header{Chain: "chain-a", Height: 80, Root: "0x80"}))
51	
52		// Two messages share one nonce combination; one will win, one replay.
53		_, err = q.Submit(relayproof.Envelope{Message: relayproof.Message{ID: "m-win", From: "chain-a", To: "chain-b", Nonce: 7, ProofAt: 100}})
54		must("submit m-win", err)
55		_, err = q.Submit(relayproof.Envelope{Message: relayproof.Message{ID: "m-lose", From: "chain-a", To: "chain-b", Nonce: 7, ProofAt: 100}})
