			t.Fatalf("stuck m1 must become replay when its nonce is consumed, got %+v", rep.Results)
		}
		if r := statusOf(t, q, "m1"); r.Status != StatusReplay ||
			!strings.Contains(r.Reason, "m2") || r.NextRetry != 0 {
			t.Fatalf("m1 replay state wrong: %+v", r)
		}
	})

